CREATE TABLE "sessions" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "token_hash" bytea NOT NULL, "subject" character varying NOT NULL, "role" character varying NOT NULL, "scopes" jsonb NULL, "csrf_key" bytea NOT NULL, "idle_expires_at" timestamptz NOT NULL, "absolute_expires_at" timestamptz NOT NULL, "last_seen_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "sessions_token_hash_key" ON "sessions" ("token_hash");
CREATE INDEX "session_token_hash" ON "sessions" ("token_hash");
CREATE INDEX "session_absolute_expires_at" ON "sessions" ("absolute_expires_at");
